// modals/ConfirmModal.ts
var import_obsidian3 = require("obsidian");
var ConfirmModal = class extends import_obsidian3.Modal {
  constructor(app, title, message, resolve) {
    super(app);
    this.title = title;
    this.message = message;
    this.settled = false;
    this.resolve = resolve;
  }
  onOpen() {
    this.modalEl.addClass("ap", "ap-modal");
    const { contentEl } = this;
    contentEl.empty();
    contentEl.createEl("h2", { text: this.title });
    const messageEl = contentEl.createDiv({ cls: "confirm-message" });
    this.message.split("\n").forEach((line, index) => {
      if (index > 0) messageEl.createEl("br");
      messageEl.appendText(line);
    });
    const buttonContainer = contentEl.createDiv({ cls: "confirm-buttons" });
    const confirmBtn = buttonContainer.createEl("button", {
      text: tr("\u786E\u8BA4", "Confirm"),
      cls: "mod-cta"
    });
    confirmBtn.onclick = () => {
      this.settle(true);
      this.close();
    };
    const cancelBtn = buttonContainer.createEl("button", {
      text: tr("\u53D6\u6D88", "Cancel"),
      cls: "mod-warning"
    });
    cancelBtn.onclick = () => {
      this.settle(false);
      this.close();
    };
    cancelBtn.focus();
  }
  onClose() {
    this.settle(false);
    const { contentEl } = this;
    contentEl.empty();
  }
  settle(value) {
    if (this.settled) return;
    this.settled = true;
    this.resolve(value);
  }
};

